var j = pm.response.json();
if (j.feasible === true) { pm.test('OPT-002: feasible=true is acceptable', function(){ pm.expect(true).to.be.true; }); }
else { pm.test('OPT-002: infeasible -> deficit present', function(){ pm.expect(j).to.have.property('deficit'); }); }

var arr = Array.isArray(pm.response.json()) ? pm.response.json() : [];
for (var i=0;i<arr.length;i++){ pm.test('REC-001 item '+i+' shape', function(){ var r=arr[i]; pm.expect(r).to.have.property('destination_id'); pm.expect(r).to.have.property('name'); pm.expect(r).to.have.property('category'); pm.expect(r).to.have.property('final_score'); pm.expect(r).to.have.property('rank'); pm.expect(r.final_score).to.be.at.most(1); pm.expect(r.final_score).to.be.at.least(0); }); }
if (arr.length > 1) { pm.test('REC-001 sorted desc by final_score', function(){
  for (var i=1;i<arr.length;i++){ pm.expect(arr[i-1].final_score).to.be.at.least(arr[i].final_score); } }); }

